THR.conversion:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const rate = get(terms, 'rate', {});
const start = get(employment, 'service_started_on', employment.effective_range.from);
// Permenaker 6/2016 art.3(1)(b): under twelve months, completed months of service to the holiday × a month's wage ÷ 12.
const on = String(get(ctx.entry, 'incurred_on', ctx.as_of));
const months = Math.min(calendar_completed_months(start, on), ctx.lookup.service_months_cap);
const output = ['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', ''));
if (rate.unit !== 'DAILY' && !output) return (ctx.month_wage * months) / 12;
// Permenaker 6/2016 art.3(3), PP 36/2021 art.19: the average received over the last 12 months. A balance holds one tax year, so an entered monthly average wins.
if (ctx.entry.unit === 'MONEY') return (ctx.entry.quantity * months) / 12;
const yearStart = ctx.as_of.slice(0, 4) + '-01-01';
const paidMonths = Number(ctx.as_of.slice(5, 7)) - Number((start > yearStart ? start : yearStart).slice(5, 7));
const paidWages = get(ctx.balances, 'ytd.ORDINARY_WAGES', 0);
if (paidMonths > 0 && paidWages > 0) return ((paidWages / paidMonths) * months) / 12;
if (rate.unit !== 'DAILY') return (ctx.month_wage * months) / 12;
// PP 36/2021 art.17: a month is 25 working days on a six-day week and 21 on a five-day week.
const sixDay = Number(get(terms, 'normal_days_per_week', 0)) === 6;
const monthDays = sixDay ? ctx.lookup.daily_paid_days_six_day : ctx.lookup.daily_paid_days_five_day;
// engine roots (full month): month_wage is salary plus fixed allowances, so a day rate's allowance part is the difference
return ((ctx.day_rate * monthDays + (ctx.month_wage - ctx.day_rate * ctx.working_days)) * months) / 12;

