OVERTIME.eligibility:
const exempt =
	get(ctx.subject.employment, 'terms.statutory_work_category', '') === 'MANAGERIAL' &&
	get(ctx.subject.employer, 'entity_extension_data.managerial_group_defined', false) === true;
