OVERTIME.conversion:
const days = get(ctx, 'work.days', []);
if (days.length === 0) return 0;
const terms = get(ctx.subject.employment, 'terms', {});
const unit = get(get(terms, 'rate', {}), 'unit', 'MONTHLY');
const sixDay = Number(get(terms, 'normal_days_per_week', 0)) === 6;
// engine roots (full month): month_wage is salary plus fixed allowances, so a day rate's allowance part is the difference
const monthly =
	unit === 'DAILY'
		? ctx.day_rate * (sixDay ? ctx.lookup.daily_paid_days_six_day : ctx.lookup.daily_paid_days_five_day) +
			(ctx.month_wage - ctx.day_rate * ctx.working_days)
		: ctx.month_wage;
// PP 35/2021 art.32(4): variable allowances are not visible after B5, so the 75% floor is applied to month_wage only.
const hourly = Math.max(
	// art.32(2): the hour is 1/173 of the month, unrounded, a daily wage's month being its day × 25 or × 21; an hourly contract's or the employer's own quoted hour stands
	unit === 'HOURLY' || get(ctx.subject.employer, 'pay_methods.overtime_hour_basis', 'STATUTORY') !== 'STATUTORY' ? ctx.hour_rate : monthly / 173,
	(ctx.lookup.wage_floor_factor * monthly) / 173
);
const premium = (day) => {
	const kind = String(get(day, 'holiday_kind', ''));
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const ordinary = (day) =>
	String(get(day, 'holiday_kind', '')) === 'MAKEUP_WORKDAY' ||
	(['WORK', ''].includes(String(get(day, 'day_type', ''))) && !premium(day));
const bandsOf = (day) => {
	if (ordinary(day)) return ctx.lookup.ordinary_bands;
	if (!sixDay) return ctx.lookup.five_day_bands;
	return String(get(day, 'day_type', '')) === 'WORK' &&
		Number(get(day, 'scheduled_hours', 0)) <= ctx.lookup.short_day_hours
		? ctx.lookup.six_day_short_bands
		: ctx.lookup.six_day_bands;
};
// the employer's rest-day hourly multiple stands on each weekly rest day it pays more than art.31(2)–(3)
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
const price = (day) => {
	const hours = ordinary(day)
		? Number(get(day, 'overtime_hours', 0))
		: Number(get(day, 'worked_hours', 0)) - Number(get(day, 'banked_hours', 0));
	if (hours <= 0) return 0;
	const statutory = ladder(hours, bandsOf(day)) * hourly;
	return ordinary(day) || premium(day) ? statutory : Math.max(statutory, hours * multiple * hourly);
};
// each day's overtime is a rupiah amount of its own
return sum(days.map((day) => round(price(day), 1, 'HALF_UP')));

