const facts = get(employment, 'employee_extension_data', {});
if (employment.engagement === 'PAYEE') return false;
if (!['CITIZEN', 'RESIDENT_FOREIGNER'].includes(get(terms, 'residency_status', ''))) return false;
const severance = Number(get(facts, 'severance_tax_history.first_payment_year', 0));
const pension = Number(get(facts, 'pension_tax_history.first_payment_year', 0));
const firstYear = Math.max(severance, pension);
const year = Number(String(get(ctx.run, 'pay_date', ctx.as_of)).slice(0, 4));
