	Number(get(ctx.statutory, 'PPH21_BUKAN_PEGAWAI.employee', 0)) +
	Number(get(ctx.statutory, 'PPH26.employee', 0));
if (!(firstYear > 0)) return false;
if (!(firstYear < year - 1)) return false;
if (other !== 0) return false;
return ctx.subtotals.PENSION_BENEFIT !== ctx.subtotals.ADDITIONAL_WAGES;

