PPH21_EMPLOYER_BORNE.employee_amount:
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const tax = Number(get(ctx.statutory, 'PPH21.employee', 0)) + Number(get(ctx.statutory, 'PPH21_DTP.employee', 0));
const casual = ['DAILY', 'HOURLY'].includes(get(terms, 'rate.unit', 'MONTHLY')) ||
	['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')) ||
	get(employment, 'engagement', '') === 'PART_TIME';
const premiums =
	Number(get(ctx.statutory, 'JKK.employer', 0)) +
	Number(get(ctx.statutory, 'JKM.employer', 0)) +
	Number(get(ctx.statutory, 'KESEHATAN.employer', 0)) +
	Number(get(ctx.posted, 'BENEFIT.employer', 0));
// PMK 168/2023 art.5(3)(d)–(e): a permanent employee's income carries the employer premiums.
const income = Number(get(ctx.subtotals, 'ADDITIONAL_WAGES', 0)) + (casual ? 0 : premiums);
const items = get(ctx.run, 'kind', '') === 'OFF_CYCLE'
	? 0
	: sum(get(terms, 'employee_borne_tax_items', []).map((code) => Number(get(terms, 'allowances.' + code + '.amount', 0))));
const own = income > 0 ? round((tax * Math.min(items, income)) / income, ctx.lookup.whole_unit, 'HALF_UP') : 0;
return own - tax;

