  .map((v) => occurrence_key(['ID', 'WLKP_ESTABLISHMENT_REPORT', ctx.entry.entity_id, 'ESTABLISHMENT', v.effective_from]))
  .flatMap((key) => ctx.reads.obligation.filter((o) => o.occurrence_key === key && o.state === 'FULFILLED' && o.fulfilled_on != null))
  .map((o) => String(o.fulfilled_on))
  .toSorted();
const reported = declared == null || declared === '' ? first(fulfilled) : String(declared);
if (reported == null) return false;
const reportedMonth = Number(reported.slice(5, 7));
const reportedYear = Number(reported.slice(0, 4));
const year = Number(coverage.from.slice(0, 4));
const month = Number(coverage.from.slice(5, 7));
const dueYear = month >= reportedMonth ? year : year - 1;
if (dueYear <= reportedYear) return false;
const key = occurrence_key(['ID', 'WLKP_ANNUAL_REPORT', ctx.entry.entity_id, dueYear]);
return !ctx.reads.obligation.some((o) => o.occurrence_key === key);

