const events = get(ctx.subject.employment, 'events', []);
if (events.some((event) => event.kind === 'LONG_ILLNESS' && get(event, 'ended_on', null) == null)) return [];
const entries = ctx.reads.leave_catalog_entry.map((row) => row.id);
const dates = ctx.reads.leave_catalog_entry_day.filter((day) => entries.includes(day.leave_entry_id)).map((day) => day.incurred_on);
const sorted = dates.toSorted();
const latest = sorted[sorted.length - 1];
const near = dates.filter((date, index) => dates.indexOf(date) === index && calendar_distance_days(date, latest) <= ctx.lookup.within_days);
if (near.length < ctx.lookup.sick_days) return [];
if (ctx.reads.obligation.length > 0) return [];
return [{
	entity_id: ctx.entry.entity_id,
	employee_id: ctx.subject.employment.employee_id,
	employment_id: ctx.entry.employment_id,
