PKWT_MAXIMUM_TERM.validate:
const from = get(ctx.entry, 'signed_contract_period.from', '');
const to = get(ctx.entry, 'signed_contract_period.to', '');
const effectiveTo = get(ctx.entry, 'effective_range.to', null);
const current = get(ctx.entry, 'effective_range.from', '');
const prior = get(ctx, 'reads.employment', []).map((row) => get(row, 'effective_range.from', '')).filter((day) => day !== '');
const starts = prior.concat([current]);
const start = starts.reduce((left, right) => (left === '' || right < left ? right : left), '');
const end = add_days(add_years(start, ctx.lookup.maximum_years), -1);
if (from === '') return false;
if (to === '') return false;
if (!(to <= end)) return false;
return effectiveTo == null || effectiveTo <= end;

