SHARED_STRUCTURED_ENTITY_INPUTS.validate:
const data = get(ctx.entry, 'entity_extension_data', {});
const bad = (value, bounds) => {
    if (value == null) return get(bounds, 'required', false) === true;
    const length = String(value).length;
    if (get(bounds, 'minLength', null) != null && length < Number(bounds.minLength)) return true;
    if (get(bounds, 'maxLength', null) != null && length > Number(bounds.maxLength)) return true;
    if (get(bounds, 'integer', false) === true && Number(value) !== Math.trunc(Number(value))) return true;
    if (get(bounds, 'minimum', null) != null && Number(value) < Number(bounds.minimum)) return true;
    if (get(bounds, 'maximum', null) != null && Number(value) > Number(bounds.maximum)) return true;
    const allowed = get(bounds, 'enum', null);
    return allowed != null && !allowed.includes(value);
};
return (
    !bad(get(data, 'registration_number', null), ctx.lookup.registration_number) &&
    !bad(get(data, 'tax_registration_number', null), ctx.lookup.tax_registration_number)
);

