ANNUAL_LEAVE.payout:
// UU 13/2003 art.156(4)(a) as amended by UU 6/2023, PP 35/2021 art.40(4)(a): unused annual leave that has not lapsed is compensated on termination.
// Neither sets a day's rate; PP 36/2021 art.17 is the statute's only divisor of a month's wage into days: ÷ 25 for a six-day
// week, ÷ 21 for a five-day week.
const days = Number(get(ctx.subject.employment, 'terms.normal_days_per_week', 5));
return (ctx.month_wage / (days >= 6 ? 25 : 21)) * ctx.entry.quantity;

MEDICAL_LEAVE.paid_share:
// PP 36/2021 art.41(1): 100% of the wage for the first four months of an illness, 75% for the next four, 50% for the next four and 25% thereafter until dismissal.
if (ctx.event == null) return 1;
const months = calendar_completed_months(ctx.event.on, ctx.as_of);
return 1 - ctx.lookup.pay_steps.find((step) => step.until_month == null || months < step.until_month).unpaid_share;

MATERNITY_LEAVE.paid_share:
// UU 4/2024 art.5(2): paid in full for the first four months and 75% for the fifth and sixth; the months past the third need a doctor’s certificate of a special condition of mother or child.
if (ctx.event == null) return 1;
const months = calendar_completed_months(ctx.event.on, ctx.as_of);
return 1 - ctx.lookup.pay_steps.find((step) => step.until_month == null || months < step.until_month).unpaid_share;

WORK_ACCIDENT_LEAVE.paid_share:
// PP 44/2015 Lampiran III as amended by PP 82/2019: STMB is 100% of the wage for the first 12 months from the accident, then 50% until recovery.
if (ctx.event == null) return 1;
const months = calendar_completed_months(ctx.event.on, ctx.as_of);
return 1 - ctx.lookup.pay_steps.find((step) => step.until_month == null || months < step.until_month).unpaid_share;

JKK.employer_amount:
// PP 44/2015 art.19: upah sebulan is the contract's wage plus fixed allowances, a day's wage × 25, piece work its average.
const employment = ctx.subject.employment;
const terms = get(employment, 'terms', {});
const unit = get(terms, 'rate.unit', 'MONTHLY');
const output = ['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', ''));
// engine roots (full month): month_wage is salary plus fixed allowances, so a day/hour rate's allowance part is the difference
const fixed =
	unit === 'DAILY' || unit === 'HOURLY' ? ctx.month_wage - ctx.day_rate * ctx.working_days : 0;
const from = ctx.run.salary_coverage.from;
const yearStart = from.slice(0, 4) + '-01-01';
const started = get(employment, 'service_started_on', get(employment, 'effective_range.from', yearStart));
const paidMonths = Number(from.slice(5, 7)) - Number((started > yearStart ? started : yearStart).slice(5, 7));
const paidWages = get(ctx.balances, 'ytd.ORDINARY_WAGES', 0);
const wage = () => {
	if (unit === 'HOURLY') return Number(get(ctx.subtotals, 'BASIC', 0)) + fixed;
	if (output && paidMonths > 0 && paidWages > 0) return paidWages / paidMonths;
	if (output) return Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));
	if (unit === 'DAILY') return ctx.day_rate * ctx.lookup.bpjs_daily_wage_days + fixed;
	return ctx.month_wage;
};
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const construction = get(entity, 'construction_services', false) === true &&
	(get(employment, 'engagement', '') === 'CONTRACTOR' ||
		unit === 'DAILY' ||
		['PIECE_RATE', 'TASK_BASIS'].includes(get(terms, 'statutory_work_category', '')));
const base = Math.max(0, wage());
if (construction) return base * ctx.lookup.risk_rates.V;
return base * get(ctx.lookup.risk_rates, get(entity, 'risk_class', ''), 0);

