// UU 27/2026 art.144: a micro or small enterprise may agree a wage of at least half the minimum wage
const share = get(entity, 'entity_extension_data.enterprise_size_class', '') === 'MICRO_OR_SMALL' ? ctx.lookup.micro_small_share : 1;
return monthly >= ctx.lookup.by_region[region] * share;

HOURLY_MINIMUM_WAGE.condition:
const entity = ctx.subject.employer;
const rate = get(ctx.entry, 'terms.rate', null);
const region = get(ctx.entry, 'terms.work_region', '') || get(entity, 'entity_extension_data.region', '');
const byRegion = get(ctx.lookup, 'by_region', {});
if (!['EMPLOYEE', 'CONTRACTOR', 'PART_TIME', 'INTERN', 'APPRENTICE'].includes(get(ctx.entry, 'engagement', ''))) return false;
if (get(rate, 'unit', '') !== 'HOURLY') return false;
if (region === '') return false;
return Object.hasOwn(byRegion, region);

HOURLY_MINIMUM_WAGE.validate:
const entity = ctx.subject.employer;
