DAILY_MINIMUM_WAGE.validate:
const entity = ctx.subject.employer;
const rate = get(ctx.entry, 'terms.rate', null);
const region = get(ctx.entry, 'terms.work_region', '') || get(entity, 'entity_extension_data.region', '');
const byRegion = get(ctx.lookup, 'by_region', {});
const days = get(ctx.entry, 'terms.normal_days_per_week', null);
if (days == null) return false;
const divisor = Number(days) === 6 ? ctx.lookup.daily_paid_days_six_day : ctx.lookup.daily_paid_days_five_day;
const amount = get(rate, 'amount', null);
if (amount == null) return false;
// UU 27/2026 art.144: half the minimum for a micro or small enterprise
const share = get(entity, 'entity_extension_data.enterprise_size_class', '') === 'MICRO_OR_SMALL' ? ctx.lookup.micro_small_share : 1;
return Number(amount) >= (Number(byRegion[region]) * share) / divisor;

PESANGON.conversion:
const terms = get(ctx.subject.employment, 'terms', {});
// a daily wage's month is 30 days' wage (UU 13/2003 art.157(2) as amended); month_wage is salary plus fixed allowances, so a day rate's allowance part is the difference
const monthly =
	get(get(terms, 'rate', {}), 'unit', 'MONTHLY') === 'DAILY'
		? ctx.day_rate * 30 + (ctx.month_wage - ctx.day_rate * ctx.working_days)
		: ctx.month_wage;

// art.157(4) as amended: a month below the worksite minimum wage counts at the minimum wage (not for a micro or small enterprise)
const facts = get(ctx.subject.employer, 'entity_extension_data', {});
const region = get(ctx.subject.employment, 'terms.work_region', '') || get(facts, 'region', '');
const floor = get(facts, 'enterprise_size_class', '') === 'MICRO_OR_SMALL' ? 0 : get(ctx.lookup.by_region, region, 0);
const wage = Math.max(monthly, floor);
const months = calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), get(ctx.subject.employment, 'effective_range.to', null) ?? ctx.as_of);
const agreed = get(ctx.subject.employment, 'employee_extension_data.agreed_pesangon_amount', null);
if (get(ctx.subject.employment, 'employee_extension_data.micro_small_enterprise', false) && agreed != null) return agreed;
const cause = String(get(ctx.subject.employment, 'employee_extension_data.termination_cause', null));
// every listed cause has its factor in the lookup
return wage * bracket(months, ctx.lookup.schedule) * get(ctx.lookup.cause_multiplier, cause, 1);

